// Replays every generated case through the Rust tokenizer and compares each
// get_next() call's result, delimiter flag and token offsets with C++.
#[test]
fn matches_cpp_string_tokenizer() {
    use string_tokenizer::{StringTokenizer, WhitespacePolicy};

    assert_eq!(CASES.len(), 500);
    for (i, c) in CASES.iter().enumerate() {
        let policy = if c.skip_over {
            WhitespacePolicy::SkipOver
        } else {
            WhitespacePolicy::IncludeInTokens
        };
        let mut t = StringTokenizer::with_whitespace_policy(c.input, c.delims, policy);
        t.set_options(c.options);
        t.set_quote_chars(c.quotes);

        for (pass, expected) in [c.run1, c.run2].into_iter().enumerate() {
            if pass == 1 {
                t.reset();
            }
            let mut got: Vec<Ev> = Vec::new();
            for _ in 0..200 {
                let ok = t.get_next();
                got.push((ok, t.token_is_delim(), t.token_begin(), t.token_end()));
                if !ok {
                    break;
                }
            }
            assert_eq!(
                got.as_slice(),
                expected,
                "case {i} pass {pass}: input={:?} delims={:?} quotes={:?} options={} skip_over={}",
                c.input,
                c.delims,
                c.quotes,
                c.options,
                c.skip_over
            );
        }
    }
}
